def one_color_lines(grid, axis=None):
    """Indices of rows (axis=0) or columns (axis=1) that are a single color throughout; both if axis is None."""
    h, w = len(grid), len(grid[0])
    rows = [i for i in range(h) if len(set(grid[i])) == 1]
    cols = [j for j in range(w) if len({grid[i][j] for i in range(h)}) == 1]
    return (rows, cols) if axis is None else (rows if axis == 0 else cols)

def blocks(grid):
    """The sub-grids between the one-color separator rows and columns, as a list of rows of (sub)grids."""
    rows, cols = one_color_lines(grid)
    def bands(idx, n):
        out, start = [], 0
        for i in idx + [n]:
            if i > start:
                out.append((start, i)); start = i + 1
        return out
    rb, cb = bands(rows, len(grid)), bands(cols, len(grid[0]))
    return [[crop(grid, r0, c0, r1 - r0, c1 - c0) for c0, c1 in cb] for r0, r1 in rb]

def crop(grid, top, left, height, width):
    """The height x width subgrid whose top-left cell is (top, left)."""
    return [row[left:left + width] for row in grid[top:top + height]]

def count_color(grid, color):
    """How many cells of the grid equal color."""
    return sum(v == color for row in grid for v in row)

def background(grid):
    """The most common color in the grid."""
    from collections import Counter
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def block_count_map(grid, color):
    """Counts of color in each separator-delimited block, as a grid of counts."""
    return [[count_color(b, color) for b in row] for row in blocks(grid)]

def flatten(nested):
    """A grid (list of lists) flattened row by row."""
    return [v for row in nested for v in row]

def rare_color(grid, exclude=()):
    """The least common color of the grid not in exclude."""
    from collections import Counter
    c = Counter(v for row in grid for v in row)
    return min((k for k in c if k not in exclude), key=lambda k: c[k])

def majority_color(grid, exclude=()):
    """The most common color of the grid not in exclude."""
    from collections import Counter
    c = Counter(v for row in grid for v in row)
    return max((k for k in c if k not in exclude), key=lambda k: c[k])

def components(grid, color):
    """The 4-connected components of `color`: a list of sets of (row, col) cells."""
    h, w = len(grid), len(grid[0])
    cells = {(i, j) for i in range(h) for j in range(w) if grid[i][j] == color}
    out = []
    while cells:
        seed = cells.pop()
        comp, stack = {seed}, [seed]
        while stack:
            y, x = stack.pop()
            for ny, nx in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
                if (ny, nx) in cells:
                    cells.discard((ny, nx))
                    comp.add((ny, nx))
                    stack.append((ny, nx))
        out.append(comp)
    return out

def comps(grid, c):
    """Alias of components: the 4-connected components of color c."""
    return components(grid, c)

def enclosed_regions(grid):
    """The connected regions of background cells that do not touch the grid border: lists of (row, col)."""
    bg = background(grid)
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] == bg and (i, j) not in seen:
                comp, stack = {(i, j)}, [(i, j)]
                seen.add((i, j))
                border = False
                while stack:
                    y, x = stack.pop()
                    if y in (0, h-1) or x in (0, w-1):
                        border = True
                    for ny, nx in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == bg and (ny, nx) not in seen:
                            seen.add((ny, nx))
                            comp.add((ny, nx))
                            stack.append((ny, nx))
                if not border:
                    out.append(comp)
    return out

def is_solid_rect(cells):
    """Whether a set of (row, col) cells is a completely filled axis-aligned rectangle."""
    ys = [y for y, x in cells]; xs = [x for y, x in cells]
    y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
    return len(cells) == (y1 - y0 + 1) * (x1 - x0 + 1)

def line_runs(cells):
    """The parallel straight runs of a set of (row, col) cells: (runs, horiz) when they form at least two equal runs of length > 1, else ([], False)."""
    cells = set(cells)
    if not cells:
        return [], False
    best = ([], False, -1)
    for horiz in (True, False):
        lines = {}
        for y, x in cells:
            key = y if horiz else x
            lines.setdefault(key, []).append((y, x))
        runs = [sorted(v) for k, v in sorted(lines.items())]
        if len(runs) >= 2 and len({len(r) for r in runs}) == 1 and len(runs[0]) > 1:
            if len(runs[0]) > best[2]:
                best = (runs, horiz, len(runs[0]))
    return best[0], best[1]

def split_blocks(grid):
    """Split by full one-color separator lines (non-background color): (separator colors, first block, second block) for a single separator."""
    bg = background(grid)
    rows, cols = separator_lines(grid)
    rows = [i for i in rows if grid[i][0] != bg] or rows
    cols = [j for j in cols if grid[0][j] != bg] or cols
    seps = {grid[i][0] for i in rows} | {grid[0][j] for j in cols}
    if rows:
        i = rows[0]
        return seps, [r[:] for r in grid[:i]], [r[:] for r in grid[i+1:]]
    if cols:
        j = cols[0]
        return seps, [r[:j] for r in grid], [r[j+1:] for r in grid]
    return seps, grid, []

def _blocks(grid):
    """The maximal subgrids between full separator lines, as (row indices, col indices) pairs."""
    rows, cols = separator_lines(grid)
