        for comp in components(grid, color):
            ys = [y for y, x in comp]; xs = [x for y, x in comp]
            y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
            ring = {(y, x) for y in range(y0, y1 + 1) for x in range(x0, x1 + 1)
                    if y in (y0, y1) or x in (x0, x1)}
            if comp == ring:
                interior = [(y, x) for y in range(y0 + 1, y1) for x in range(x0 + 1, x1)]
                v = fill(len(interior))
                for y, x in interior:
                    out[y][x] = v
    return out

def vflip(grid):
    """The rows in reverse order: the grid mirrored top to bottom."""
    return grid[::-1]

def vstack(*grids):
    """Two or more grids of equal width stacked one above the other."""
    out = []
    for g in grids: out += g
    return out

def fill_between_walls(grid, wall, fill=3):
    """Non-wall cells with a wall both above and below in their column, or both left and right in their row, become `fill`."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for i in range(h):
        for j in range(w):
            if grid[i][j] == wall: continue
            colw = [r for r in range(h) if grid[r][j] == wall]
            roww = [c for c in range(w) if grid[i][c] == wall]
            if (any(r < i for r in colw) and any(r > i for r in colw)) or                (any(c < j for c in roww) and any(c > j for c in roww)):
                out[i][j] = fill
    return out


def background(grid):
    """The most common color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def components(grid, color):
    """The 4-connected components of `color`: a list of sets of (row, col) cells."""
    h, w = len(grid), len(grid[0])
    cells = {(i, j) for i in range(h) for j in range(w) if grid[i][j] == color}
    out = []
    while cells:
        seed = cells.pop()
        comp, stack = {seed}, [seed]
        while stack:
            y, x = stack.pop()
            for ny, nx in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
                if (ny, nx) in cells:
                    cells.discard((ny, nx))
                    comp.add((ny, nx))
                    stack.append((ny, nx))
        out.append(comp)
    return out

def comps(grid, c):
    """Alias of components: the 4-connected components of color c."""
    return components(grid, c)

def enclosed_regions(grid):
    """The connected regions of background cells that do not touch the grid border: lists of (row, col)."""
    bg = background(grid)
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] == bg and (i, j) not in seen:
                comp, stack = {(i, j)}, [(i, j)]
                seen.add((i, j))
                border = False
                while stack:
                    y, x = stack.pop()
                    if y in (0, h-1) or x in (0, w-1):
                        border = True
                    for ny, nx in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == bg and (ny, nx) not in seen:
                            seen.add((ny, nx))
                            comp.add((ny, nx))
                            stack.append((ny, nx))
                if not border:
                    out.append(comp)
    return out

def is_solid_rect(cells):
    """Whether a set of (row, col) cells is a completely filled axis-aligned rectangle."""
    ys = [y for y, x in cells]; xs = [x for y, x in cells]
    y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
    return len(cells) == (y1 - y0 + 1) * (x1 - x0 + 1)

def line_runs(cells):
    """The parallel straight runs of a set of (row, col) cells: (runs, horiz) when they form at least two equal runs of length > 1, else ([], False)."""
    cells = set(cells)
    if not cells:
        return [], False
    best = ([], False, -1)
    for horiz in (True, False):
        lines = {}
        for y, x in cells:
            key = y if horiz else x
            lines.setdefault(key, []).append((y, x))
        runs = [sorted(v) for k, v in sorted(lines.items())]
        if len(runs) >= 2 and len({len(r) for r in runs}) == 1 and len(runs[0]) > 1:
            if len(runs[0]) > best[2]:
                best = (runs, horiz, len(runs[0]))
    return best[0], best[1]

def split_blocks(grid):
    """Split by full one-color separator lines (non-background color): (separator colors, first block, second block) for a single separator."""
    bg = background(grid)
    rows, cols = separator_lines(grid)
    rows = [i for i in rows if grid[i][0] != bg] or rows
    cols = [j for j in cols if grid[0][j] != bg] or cols
    seps = {grid[i][0] for i in rows} | {grid[0][j] for j in cols}
    if rows:
        i = rows[0]
        return seps, [r[:] for r in grid[:i]], [r[:] for r in grid[i+1:]]
    if cols:
        j = cols[0]
        return seps, [r[:j] for r in grid], [r[j+1:] for r in grid]
    return seps, grid, []

def _blocks(grid):
    """The maximal subgrids between full separator lines, as (row indices, col indices) pairs."""
    rows, cols = separator_lines(grid)
    rr = [i for i in range(len(grid)) if i not in rows]
    cc = [j for j in range(len(grid[0])) if j not in cols]
    out = []
    for grp in [[list(g) for g in __import__('itertools').groupby(sorted(rr), key=lambda i: i - rr.index(i))]]:
        pass
    # contiguous runs of kept rows/cols
    def runs(idx):
        out, cur = [], []
        for i in idx:
            if cur and i == cur[-1] + 1: cur.append(i)
            else:
                if cur: out.append(cur)
                cur = [i]
        if cur: out.append(cur)
        return out
    return [(r, c) for r in runs(rr) for c in runs(cc)]

def block_grid(grid):
    """The grid's separator-delimited blocks: a list of rows of (row indices, col indices)."""
    cells = _blocks(grid)
    rs = sorted({r[0] for r, c in cells})
    rows = {}
    for r, c in cells:
        rows.setdefault(r[0], []).append((r, c))
    return [rows[k] for k in rs]

def pattern_blocks(grid):
    """The separator-delimited blocks grouped by identical content: a list of groups of block subgrids."""
    groups = {}
    for r, c in _blocks(grid):
        b = tuple(tuple(grid[i][j] for j in c) for i in r)
        groups.setdefault(b, []).append([list(t) for t in b])
    return list(groups.values())

def rotate_cw(grid, k=1):
    """The grid rotated 90 degrees clockwise k times."""
    for _ in range(k % 4):
        grid = [list(r) for r in zip(*grid[::-1])]
    return grid

def rotate_ccw(grid, k=1):
    """The grid rotated 90 degrees counter-clockwise k times."""
    return rotate_cw(grid, 4 - (k % 4) if k % 4 else 0) if k % 4 else [r[:] for r in grid]

def rot180(grid):
    """The grid rotated 180 degrees."""
    return [r[::-1] for r in grid[::-1]]

def norm_shape(cells):
    """A set of (row, col) cells translated so its top-left is at the origin, as a sorted tuple."""
    y0 = min(y for y, x in cells); x0 = min(x for y, x in cells)
    return tuple(sorted((y - y0, x - x0) for y, x in cells))

def l_stroke(grid, bg):
    """Find the L-shaped stroke (two perpendicular runs sharing a corner cell): (its color, its cells as a set)."""
    h, w = len(grid), len(grid[0])
    for c in {v for row in grid for v in row} - {bg}:
        cells = {(i, j) for i in range(h) for j in range(w) if grid[i][j] == c}
        if len(cells) < 3:
            continue
        ys = [y for y, x in cells]; xs = [x for y, x in cells]
        # an L: every cell on the bounding box edge rows/cols through the corner, no interior cells
        for cy, cx in cells:
            vert = {(y, cx) for y, x in cells}
            hor = {(cy, x) for y, x in cells}
            if (vert | hor) == cells and len(vert) >= 2 and len(hor) >= 2:
                return c, cells
    return None, set()

def fill_ring_interiors(grid, fill=None):
    """Every component that is exactly a hollow rectangle ring gets its enclosed interior cells recolored; fill(area) gives the new color (default area-2 capped at 7, minimum 7)."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    if fill is None:
        fill = lambda area: area - 2 if 0 < area - 2 <= 7 else 7
    for color in {v for row in grid for v in row}:
        for comp in components(grid, color):
            ys = [y for y, x in comp]; xs = [x for y, x in comp]
            y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
            ring = {(y, x) for y in range(y0, y1 + 1) for x in range(x0, x1 + 1)
                    if y in (y0, y1) or x in (x0, x1)}
            if comp == ring:
                interior = [(y, x) for y in range(y0 + 1, y1) for x in range(x0 + 1, x1)]
                v = fill(len(interior))
                for y, x in interior:
                    out[y][x] = v
    return out

def hstack(a, b):
    """Two grids of equal height joined side by side."""
    return [ra + rb for ra, rb in zip(a, b)]

def intersect_blocks(grid, color=2):
    """Cells non-zero in every patterned block, recolored; a single block maps to itself."""
    bl = [b for grp in pattern_blocks(grid) for b in grp
          if any(len(set(row)) > 1 for row in b)]
    if len(bl) > 1:
        sizes = Counter((len(b), len(b[0])) for b in bl)
        mode = sizes.most_common(1)[0][0]
        bl = [b for b in bl if (len(b), len(b[0])) == mode]
    if len(bl) == 1:
        return [[color if v else 0 for v in row] for row in bl[0]]
    h, w = len(bl[0]), len(bl[0][0])
    return [[color if all(b[i][j] != 0 for b in bl) else 0 for j in range(w)] for i in range(h)]

def paired_beam_fill(grid, junction=4):
    """Two parallel marker runs and seed cells: each seed beams toward its run's cell (seed becomes `junction`),
    and the other run's cell at the same offset beams across the full line; both beams take the seed's color."""
    from collections import Counter
    h,w=len(grid),len(grid[0])
    cnt=Counter(v for r in grid for v in r)
    bg=cnt.most_common(1)[0][0]
    nonbg=[v for v,_ in cnt.most_common() if v!=bg]
    marker=None
    for v in nonbg:
        cells=[(i,j) for i in range(h) for j in range(w) if grid[i][j]==v]
        r,hz=line_runs(cells)
        if r: marker,R,horiz=v,r,hz
    seed=[v for v in nonbg if v!=marker][0]
    d1={k:c for k,c in enumerate(R[0])}; d2={k:c for k,c in enumerate(R[1])}
    out=[row[:] for row in grid]
    for (i,j) in [(i,j) for i in range(h) for j in range(w) if grid[i][j]==seed]:
        out[i][j]=junction
        for D,other in ((d1,d2),(d2,d1)):
            for k,(ri,rj) in D.items():
                if (horiz and j==rj) or (not horiz and i==ri):
                    oi,oj=other[k]
                    if horiz:
                        step=1 if ri>i else -1
                        for x in range(i+step,ri,step): out[x][j]=seed
                        for x in range(h):
                            if x!=oi: out[x][oj]=seed
                    else:
                        step=1 if rj>j else -1
                        for y in range(j+step,rj,step): out[i][y]=seed
                        for y in range(w):
                            if y!=oj: out[oi][y]=seed
                    break
            else: continue
            break
    return out

def recolor_small_to_large_zero(grid):
    """The smaller of the grid's two colors becomes the larger, and the larger becomes 0."""
    vs = {v for row in grid for v in row}
    lo, hi = min(vs), max(vs)
    return [[hi if v == lo else (0 if v == hi else v) for v in row] for row in grid]

def separator_lines(grid):
    """Indices of rows and of columns that are one color throughout (full grid lines)."""
    H, W = len(grid), len(grid[0])
    rows = [i for i, r in enumerate(grid) if len(set(r)) == 1]
    cols = [j for j in range(W) if len({r[j] for r in grid}) == 1]
    return rows, cols

def shared_color_mark(grid, mark=3):
    """The two blocks split by a full separator line, marked where both blocks show the color they share; that shared color elsewhere."""
    _, A, B = split_blocks(grid)
    shared = ({v for r in A for v in r} & {v for r in B for v in r}).pop()
    return [[mark if a == shared and b == shared else shared for a, b in zip(ra, rb)] for ra, rb in zip(A, B)]

def stamp_marker_motif(grid, bg=None, noise=None, anchor=None):
    """Stamp the grid's small multi-color motif centered on every isolated noise dot."""
    from collections import Counter as _C
    bg = bg if bg is not None else background(grid)
    cnt = _C(v for r in grid for v in r)
    cands = [c for c in cnt if c != bg]
    noise = noise if noise is not None else max(cands, key=lambda c: cnt[c])
    ys = [y for y, r in enumerate(grid) for x, v in enumerate(r) if v not in (bg, noise)]
    xs = [x for y, r in enumerate(grid) for x, v in enumerate(r) if v not in (bg, noise)]
    y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
    motif = [row[x0:x1 + 1] for row in grid[y0:y1 + 1]]
    H, W = len(motif), len(motif[0])
    ay, ax = anchor if anchor is not None else ((H - 1) // 2, (W - 1) // 2)
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for y in range(h):
        for x in range(w):
            if grid[y][x] == noise:
                for dy in range(H):
                    for dx in range(W):
                        yy, xx = y + dy - ay, x + dx - ax
                        if 0 <= yy < h and 0 <= xx < w:
                            out[yy][xx] = motif[dy][dx]
    return out

def stamp_shape_on_fitting_spots(grid, color, bg=0):
    """Find the shape drawn in `color` and stamp copies everywhere it fits entirely on background cells."""
    H, W = len(grid), len(grid[0])
    cells = [(i, j) for i in range(H) for j in range(W) if grid[i][j] == color]
    if not cells:
        return [row[:] for row in grid]
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    shape = [(r - r0, c - c0) for r, c in cells]
    out = [row[:] for row in grid]
    for di in range(H):
        for dj in range(W):
            targets = [(di + sr, dj + sc) for sr, sc in shape]
            if all(0 <= i < H and 0 <= j < W and grid[i][j] == bg for i, j in targets):
                for i, j in targets:
                    out[i][j] = color
    return out

def tile_rotations_quadrants(grid):
    """The grid tiled 2x2: top-left as-is, top-right rotated 90 clockwise, bottom-right 180, bottom-left 270."""
    n, w = len(grid), len(grid[0])
    tl = grid
    tr = rotate_cw(grid, 1)
    br = rot180(grid)
    bl = rotate_ccw(grid, 1)
    return vstack(hstack(tl, tr), hstack(bl, br))

def vflip(grid):
    """The rows in reverse order: the grid mirrored top to bottom."""
    return grid[::-1]

def vstack(*grids):
    """Two or more grids of equal width stacked one above the other."""
    out = []
    for g in grids: out += g
    return out

def fill_between_walls(grid, wall, fill=3):
    """Non-wall cells with a wall both above and below in their column, or both left and right in their row, become `fill`."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for i in range(h):
        for j in range(w):
            if grid[i][j] == wall: continue
            colw = [r for r in range(h) if grid[r][j] == wall]
            roww = [c for c in range(w) if grid[i][c] == wall]
            if (any(r < i for r in colw) and any(r > i for r in colw)) or                (any(c < j for c in roww) and any(c > j for c in roww)):
                out[i][j] = fill
    return out


def background(grid):
    """The most common color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def components(grid, color):
    """The 4-connected components of `color`: a list of sets of (row, col) cells."""
    h, w = len(grid), len(grid[0])
    cells = {(i, j) for i in range(h) for j in range(w) if grid[i][j] == color}
    out = []
    while cells:
        seed = cells.pop()
        comp, stack = {seed}, [seed]
        while stack:
            y, x = stack.pop()
            for ny, nx in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
                if (ny, nx) in cells:
                    cells.discard((ny, nx))
                    comp.add((ny, nx))
                    stack.append((ny, nx))
        out.append(comp)
    return out

def comps(grid, c):
    """Alias of components: the 4-connected components of color c."""
    return components(grid, c)

def enclosed_regions(grid):
    """The connected regions of background cells that do not touch the grid border: lists of (row, col)."""
    bg = background(grid)
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] == bg and (i, j) not in seen:
                comp, stack = {(i, j)}, [(i, j)]
                seen.add((i, j))
                border = False
                while stack:
                    y, x = stack.pop()
                    if y in (0, h-1) or x in (0, w-1):
                        border = True
                    for ny, nx in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == bg and (ny, nx) not in seen:
                            seen.add((ny, nx))
                            comp.add((ny, nx))
                            stack.append((ny, nx))
                if not border:
                    out.append(comp)
    return out

def is_solid_rect(cells):
    """Whether a set of (row, col) cells is a completely filled axis-aligned rectangle."""
    ys = [y for y, x in cells]; xs = [x for y, x in cells]
    y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
    return len(cells) == (y1 - y0 + 1) * (x1 - x0 + 1)

def line_runs(cells):
    """The parallel straight runs of a set of (row, col) cells: (runs, horiz) when they form at least two equal runs of length > 1, else ([], False)."""
    cells = set(cells)
    if not cells:
        return [], False
    best = ([], False, -1)
    for horiz in (True, False):
        lines = {}
        for y, x in cells:
            key = y if horiz else x
